-- Snapshot of live, contextually linked guide revisions. Updates only on unmodified release guides lacking these links.

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"dashboard","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting"}}]},{"text":" opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Missed credits","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Need a decision","type":"text","marks":[{"type":"bold"}]},{"text":": an exception with no makegood yet, or one the agency declined.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Waiting on the agency","type":"text","marks":[{"type":"bold"}]},{"text":": the order''s makegoods need the agency''s approval, and no answer is recorded yet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makegoods awaiting a break","type":"text","marks":[{"type":"bold"}]},{"text":": the next auto-fill places these first.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scheduling","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Units not yet scheduled","type":"text","marks":[{"type":"bold"}]},{"text":": open periods on active contracts that auto-fill hasn''t reached yet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Capacity conflicts","type":"text","marks":[{"type":"bold"}]},{"text":": lines that can''t be placed in the next 14 days, listed below with what''s blocking each one.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"To record in DAD","type":"text","marks":[{"type":"bold"}]},{"text":": messages under a new DAD cut that production hasn''t marked recorded yet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Affidavits","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"To generate","type":"text","marks":[{"type":"bold"}]},{"text":": contracts with aired credits not yet covered by an affidavit.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Awaiting your signature","type":"text","marks":[{"type":"bold"}]},{"text":": generated affidavits ready to sign. Only underwriting managers see this one.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Auto-fill everything","type":"text","marks":[{"type":"bold"}]},{"text":" in the right-hand column to fill every active contract''s open periods, makegoods first.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If you can open On Air, ","type":"text"},{"text":"Log of record","type":"text","marks":[{"type":"bold"}]},{"text":" in the right-hand column shows whether the DAD log is released for today and the next two days.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Finding your way","type":"text"}]},{"type":"paragraph","content":[{"text":"Traffic has five tabs, one for each kind of job:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dashboard","type":"text","marks":[{"type":"bold"}]},{"text":" is this page.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Contracts","type":"text","marks":[{"type":"bold"}]},{"text":" is every agreement, and where schedules, copy and placements are worked.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Needs attention","type":"text","marks":[{"type":"bold"}]},{"text":" holds Exceptions and Affidavits. The number beside the tab counts exceptions waiting on a decision, plus affidavits waiting for a signature if you are an underwriting manager, and disappears when there are none. Choose Exceptions or Affidavits in the grey row beneath the tabs.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Library","type":"text","marks":[{"type":"bold"}]},{"text":" holds Underwriters and Copy.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Setup","type":"text","marks":[{"type":"bold"}]},{"text":" sits at the right edge: inventory pools, industries and the migration of legacy records.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The grey row beneath a tab lists that tab''s pages. The page you are on has a grey background.","type":"text"}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-dashboard' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Contracts","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"text":" page lists every underwriting contract, with search and filters in one row above it.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Search by underwriter name or order number.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use the chips to show all contracts, active ones, drafts, or the ones that need attention — a draft, or a contract with an open exception.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"+ New contract","type":"text","marks":[{"type":"bold"}]},{"text":" to start the setup steps for a new order.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-find-contracts' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"An ","type":"text"},{"text":"exception","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/exceptions"}}]},{"text":" appears the moment a host records an underwriting credit as missed or moved. There''s nothing to check for: if a credit didn''t air as scheduled, it''s on this list.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"The list","type":"text"}]},{"type":"paragraph","content":[{"text":"Each row is one missed credit, with its makegood beside it. The filters follow the steps of resolving a miss, and the list opens on the first one with anything in it:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Need a decision","type":"text","marks":[{"type":"bold"}]},{"text":": no makegood yet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Waiting on the agency","type":"text","marks":[{"type":"bold"}]},{"text":": the order says the agency approves makegoods, and it hasn''t answered.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makegood awaiting a break","type":"text","marks":[{"type":"bold"}]},{"text":": a makegood exists; auto-fill will place it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makegood scheduled","type":"text","marks":[{"type":"bold"}]},{"text":": its break is chosen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Resolved","type":"text","marks":[{"type":"bold"}]},{"text":" and ","type":"text"},{"text":"All","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Working an exception","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If the order needs the agency''s approval, record its answer under ","type":"text"},{"text":"Agency''s answer","type":"text","marks":[{"type":"bold"}]},{"text":". Nothing schedules a makegood until then.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Under ","type":"text"},{"text":"Makegood","type":"text","marks":[{"type":"bold"}]},{"text":", select ","type":"text"},{"text":"Create a makegood","type":"text","marks":[{"type":"bold"}]},{"text":". By default auto-fill places it, ahead of regular credits. To choose the break yourself, select ","type":"text"},{"text":"Pick a break now","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Under ","type":"text"},{"text":"Resolve","type":"text","marks":[{"type":"bold"}]},{"text":", choose what happens: make it good, accept the alternate airing, waive, or close with no action. Rarer decisions are under ","type":"text"},{"text":"More decisions","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An exception closes itself when its last makegood airs. There''s no separate step to close it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A makegood counts toward the period the original credit missed, so it never counts as an extra unit.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Waiving a credit needs an underwriting manager.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A resolved exception can be reopened from its own page.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-exceptions-and-makegoods' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"contract''s page","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"text":" has three tabs.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Schedule","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Each line of the order, with its progress. Switch to ","type":"text"},{"text":"By date","type":"text","marks":[{"type":"bold"}]},{"text":" to see every placement in air order, filtered to upcoming, aired, or not aired.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"When the order changes, select ","type":"text"},{"text":"Revise the schedule","type":"text","marks":[{"type":"bold"}]},{"text":". A draft revision shows as a banner; ","type":"text"},{"text":"Review and activate","type":"text","marks":[{"type":"bold"}]},{"text":" shows exactly what it would clear before you confirm.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Flights, for orders grouped by event, are at the bottom of the tab.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Copy","type":"text"}]},{"type":"paragraph","content":[{"text":"The messages this contract runs, and how they rotate.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Agreement","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The signed agreement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The traffic policy, shown as read. Select ","type":"text"},{"text":"Edit","type":"text","marks":[{"type":"bold"}]},{"text":" to change it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The contract''s affidavits.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Its revision history.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-contract-page' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"project","type":"text","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"text":" can draw on more than one recording or document. When the same interview matters to more than one story, add it to each project instead of uploading it again. Every project then shares one original and one transcript.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Add a source","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the project. It opens on a card for each source it references.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"+ Add source","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On ","type":"text"},{"text":"Find existing","type":"text","marks":[{"type":"bold"}]},{"text":", search for the source by title and choose it. It is added right away, with no confirmation step.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Upload new","type":"text","marks":[{"type":"bold"}]},{"text":" in the same window adds a recording or PDF that isn''t in Sourcework yet.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Switch between sources","type":"text"}]},{"type":"paragraph","content":[{"text":"Select a card to open that source''s transcript, media, and excerpts. The page address changes to include ","type":"text"},{"text":"?source=","type":"text","marks":[{"type":"code"}]},{"text":", so you can send a colleague a link straight to it. ","type":"text"},{"text":"← All sources in this project","type":"text","marks":[{"type":"bold"}]},{"text":" goes back to the cards.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An excerpt belongs to the source that was open when you made it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retrying a failed transcription retries the open source, not the project''s first one.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"PDF documents are added the same way as audio. They open in the document viewer instead of the player.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='sourcework-reference-another-source' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Source Library","type":"text","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=sources"}}]},{"text":" lists every recording and document uploaded to Sourcework, independent of the projects that use them. Open it from the ","type":"text"},{"text":"Sources","type":"text","marks":[{"type":"bold"}]},{"text":" tab on the Sourcework home page.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Open a source","type":"text"}]},{"type":"paragraph","content":[{"text":"Select a source to open its own page. It shows the same working surface a project does — the player, transcript, and excerpts for audio and video, or the page viewer and text for a PDF — plus the list of projects that reference it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A source is the original recording or document. It is never edited; a project is the work that refers to it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"To use a source in another story, open that project, select ","type":"text"},{"text":"+ Add source","type":"text","marks":[{"type":"bold"}]},{"text":", and find it on ","type":"text"},{"text":"Find existing","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='sourcework-browse-source-library' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Administrators use this screen to bring agreements from the station''s legacy records into Traffic. Open it from the ","type":"text"},{"text":"Contracts list","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"text":": ","type":"text"},{"text":"Migrate legacy records","type":"text","marks":[{"type":"bold"}]},{"text":". It lists every batch with how far along it is and what it needs next.","type":"text"},{"text":" Agreements are the first of its two tabs; active copy from RadioTraffic comes in on the second, Copy.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Start a batch","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"New batch","type":"text","marks":[{"type":"bold"}]},{"text":", name the batch, and choose where the facts come from: ","type":"text"},{"text":"A spreadsheet of agreements","type":"text","marks":[{"type":"bold"}]},{"text":" (recommended) or ","type":"text"},{"text":"Documents only","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can''t be read, or whose sponsor isn''t on file, is listed first. When a close name is on file, select ","type":"text"},{"text":"Use it","type":"text","marks":[{"type":"bold"}]},{"text":"; otherwise add the underwriter under Underwriters and load the manifest again.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Load and continue","type":"text","marks":[{"type":"bold"}]},{"text":". Rows that still need a fix are left out.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The manifest needs the underwriter and the document''s file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. ","type":"text"},{"text":"Download a template","type":"text","marks":[{"type":"bold"}]},{"text":" gives the column names.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the documents","type":"text"}]},{"type":"paragraph","content":[{"text":"Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn''t match cleanly is listed under ","type":"text"},{"text":"Needs attention","type":"text","marks":[{"type":"bold"}]},{"text":" with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn''t name can be imported too, with every fact read from the document.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Import","type":"text"}]},{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Import","type":"text","marks":[{"type":"bold"}]},{"text":". Three agreements are read at a time, each the same way ","type":"text"},{"text":"Create from the agreement","type":"text","marks":[{"type":"bold"}]},{"text":" reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select ","type":"text"},{"text":"Stop after the ones reading","type":"text","marks":[{"type":"bold"}]},{"text":". If the reading service asks the portal to slow down, the run pauses and carries on by itself.","type":"text"}]},{"type":"paragraph","content":[{"text":"The manifest''s facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Review","type":"text"}]},{"type":"paragraph","content":[{"text":"The batch page opens on ","type":"text"},{"text":"Needs a look","type":"text","marks":[{"type":"bold"}]},{"text":": drafts where the document disagrees with the manifest, or where an instruction couldn''t be saved as a schedule line. Open a row to see each disagreement side by side, and select ","type":"text"},{"text":"Enter on the schedule","type":"text","marks":[{"type":"bold"}]},{"text":" for the lines to enter by hand. ","type":"text"},{"text":"Ready to activate","type":"text","marks":[{"type":"bold"}]},{"text":" means nothing was flagged; the draft still needs a look before it''s activated. A failed entry shows why; fix the cause and select ","type":"text"},{"text":"Run again","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Running it again","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Importing again never creates a second contract for an entry that already has one.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Loading a corrected manifest under the same batch name updates entries that haven''t been imported. Keep each row''s key the same.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"To redo an imported entry, delete its draft contract; the entry can then be imported again.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A document that has already been imported, under any entry, is not imported again.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-migrate-legacy-agreements' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Administrators use this screen once, to bring the station''s active underwriting copy in from RadioTraffic. Open it from the ","type":"text"},{"text":"Contracts list","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"text":" (","type":"text"},{"text":"Migrate legacy records","type":"text","marks":[{"type":"bold"}]},{"text":", then the ","type":"text"},{"text":"Copy","type":"text","marks":[{"type":"bold"}]},{"text":" tab) or from the Copy library (","type":"text"},{"text":"Import from RadioTraffic","type":"text","marks":[{"type":"bold"}]},{"text":").","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the export","type":"text"}]},{"type":"paragraph","content":[{"text":"In RadioTraffic''s “Active Copy by Underwriter” workbook, use File › Save As › CSV, then choose that file. Title lines above the header row are fine. Columns are found by name: Underwriter, Copy Name, Cart, Length, Start Date, End Date and Script. Nothing is written until you import.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Review","type":"text"}]},{"type":"paragraph","content":[{"text":"Most rows need nothing from you. The screen leads with the few questions it can''t answer on its own, each with a short set of choices:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"New underwriter","type":"text","marks":[{"type":"bold"}]},{"text":": a name that isn''t on file. Add it, choose the underwriter it really is, or leave its rows out.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Which contract","type":"text","marks":[{"type":"bold"}]},{"text":": more than one agreement covers the copy''s dates, or the copy is for a product (a Learning Minute) no agreement is for. The answer covers all of that underwriter''s copy, so a rotation is never split between contracts.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Which flight","type":"text","marks":[{"type":"bold"}]},{"text":": event copy whose name fits more than one flight.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Changed wording","type":"text","marks":[{"type":"bold"}]},{"text":": the portal has copy with the same name and cart but different words. Where the difference is a few characters, the portal''s copy is usually the damaged one and using RadioTraffic''s wording is recommended; where the portal filled in a spot number RadioTraffic leaves blank, keeping the portal''s is. A genuinely new message is added as its own copy. The portal''s copy is only changed when you choose it.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"A recommended answer is already chosen and shown folded, with Change beside it. Rows waiting on an unanswered question stay out of the import; everything else can come in now.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How rows are matched","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An underwriter is matched by name, ignoring punctuation, apostrophes, “&” and plurals. A few names RadioTraffic spells differently, such as the FPM accounts, are matched from a fixed list.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Copy already in the portal is recognised by its script, however it got there, and reused. Its dates are set to RadioTraffic''s; a missing cart is added. Nothing else about it changes.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"New copy comes in approved, with RadioTraffic''s dates. A script that asks the host to play a recorded spot is stored as recorded, at the export''s length; anything read aloud is a live read, planned at its read time. The cart number is kept as RadioTraffic''s reference.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Copy is linked to a contract only when exactly one current agreement fits its dates. App and digital agreements are never used for broadcast copy. Event copy is scoped to the flight it names. Linked copy joins that contract''s rotation; copy with no agreement stays with its underwriter and can be linked later from the contract''s Copy tab.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Placeholders (“copy holder”) and rows that aren''t underwriting copy, such as the EAS test, are left out. WUWF Day Sponsor copy comes in under its own underwriter with no contract.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Running it again","type":"text"}]},{"type":"paragraph","content":[{"text":"It is safe to run the same export again, or a newer one. Copy already here is recognised and skipped, links that exist are left alone, and a message that failed the first time is picked up. Each import is recorded in the audit log.","type":"text"}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-migrate-legacy-copy' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"planning meeting","type":"text","marks":[{"type":"link","attrs":{"href":"/editorial/meetings"}}]},{"text":" moves through three stages: ","type":"text"},{"text":"Scoring open","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Agenda","type":"text","marks":[{"type":"bold"}]},{"text":", and ","type":"text"},{"text":"Concluded","type":"text","marks":[{"type":"bold"}]},{"text":". Editors run it; reviewers and editors score; contributors can follow along.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Set it up (editors)","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Meetings tab, choose the meeting date and a rubric profile, then select ","type":"text"},{"text":"Create meeting","type":"text","marks":[{"type":"bold"}]},{"text":". Pick Immediate / Emerging News when the slate is mostly urgent coverage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the meeting. Under ","type":"text"},{"text":"+ Add pitch","type":"text","marks":[{"type":"bold"}]},{"text":", choose a pitch from the backlog and select ","type":"text"},{"text":"Add to slate","type":"text","marks":[{"type":"bold"}]},{"text":". Repeat for each pitch.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Score the slate (reviewers and editors)","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open each pitch on the slate. ","type":"text"},{"text":"Show pitch details","type":"text","marks":[{"type":"bold"}]},{"text":" expands the full pitch.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a score for each criterion. Hover a number to read what it means. Institutional modifiers are optional.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a recommendation, flag any concerns, and add a comment if it helps the room. Select ","type":"text"},{"text":"Save review","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Scoring is independent: nobody sees anyone else''s scores or comments until the editor closes scoring.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Decide (editors)","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Close scoring & build agenda","type":"text","marks":[{"type":"bold"}]},{"text":". The slate is ranked by score.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A red ","type":"text"},{"text":"Split","type":"text","marks":[{"type":"bold"}]},{"text":" badge means reviewers disagree — worth discussing. Open ","type":"text"},{"text":"Scores, recommendations & comments","type":"text","marks":[{"type":"bold"}]},{"text":" to see why.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For each pitch, choose ","type":"text"},{"text":"Assign","type":"text","marks":[{"type":"bold"}]},{"text":" (pick the reporter first), ","type":"text"},{"text":"Defer","type":"text","marks":[{"type":"bold"}]},{"text":" to keep it in the backlog, or ","type":"text"},{"text":"Archive","type":"text","marks":[{"type":"bold"}]},{"text":". Select ","type":"text"},{"text":"Change","type":"text","marks":[{"type":"bold"}]},{"text":" to revise a decision.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Conclude meeting","type":"text","marks":[{"type":"bold"}]},{"text":". Any pitch still undecided is deferred. A concluded meeting is a permanent record.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='editorial-run-a-planning-meeting' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Every story idea starts as a pitch in the ","type":"text"},{"text":"backlog","type":"text","marks":[{"type":"link","attrs":{"href":"/editorial"}}]},{"text":". An editor picks pitches from the backlog for a weekly planning meeting, where reviewers score them and the editor records a decision.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Submit one","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Backlog tab, select ","type":"text"},{"text":"New pitch","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Give it a title — one line that says what the story is — and fill in the fields below it. Fields marked with an asterisk are required.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a ","type":"text"},{"text":"Primary coverage pillar","type":"text","marks":[{"type":"bold"}]},{"text":". If you choose one of the station''s pillars, say how the story contributes to sustained coverage of it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Submit pitch","type":"text","marks":[{"type":"bold"}]},{"text":". You land on the pitch''s own page.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Edit it","type":"text"}]},{"type":"paragraph","content":[{"text":"You can keep editing your pitch with ","type":"text"},{"text":"Edit","type":"text","marks":[{"type":"bold"}]},{"text":" until an editor adds it to a meeting''s slate. While that meeting is scoring, edits are locked; they reopen if the pitch comes back to the backlog.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Follow it","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Backlog has four views: ","type":"text"},{"text":"Open","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Stale","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Assigned","type":"text","marks":[{"type":"bold"}]},{"text":", and ","type":"text"},{"text":"Archived","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A pitch is stale when it has gone 90 days without a review, or has been deferred three times. Editors can archive stale pitches in bulk from the Stale view.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The pitch page''s ","type":"text"},{"text":"Review history","type":"text","marks":[{"type":"bold"}]},{"text":" lists each meeting that discussed it, with its scores, reviewers'' comments, and the decision.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Once a pitch is assigned, the reporter or an editor can start its story plan from the pitch page.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='editorial-submit-a-pitch' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Affidavits","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/affidavits"}}]},{"text":" are one list per month, with a row for every contract that aired credits that month. A row''s button shows where it stands: ","type":"text"},{"text":"Generate","type":"text","marks":[{"type":"bold"}]},{"text":", then ","type":"text"},{"text":"Sign","type":"text","marks":[{"type":"bold"}]},{"text":", then ","type":"text"},{"text":"Signed","type":"text","marks":[{"type":"bold"}]},{"text":" with its PDF.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Each month","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open ","type":"text"},{"text":"Affidavits","type":"text","marks":[{"type":"bold"}]},{"text":". It opens on last month.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Generate","type":"text","marks":[{"type":"bold"}]},{"text":" on one row, or ","type":"text"},{"text":"Generate","type":"text","marks":[{"type":"bold"}]},{"text":" with a count at the top to do every row still waiting. A row that fails says why, and the rest still generate.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Whoever signs selects ","type":"text"},{"text":"Sign","type":"text","marks":[{"type":"bold"}]},{"text":" with a count at the top, then ","type":"text"},{"text":"Sign and open next","type":"text","marks":[{"type":"bold"}]},{"text":" on each one. Previous and Skip move through the month without signing.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Signing","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Your title on the signature line comes from your profile. Changing it while signing applies to that affidavit only. An administrator sets titles under Admin › Users.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Signing stores the PDF, and it can''t be changed afterwards. A correction is a new affidavit; the list shows the earlier version beside it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Only underwriting managers can sign. Everyone else sees “Waiting for signature” and can preview the draft.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use the arrows beside the month to see earlier months. A note at the top names any earlier month that still has affidavits to generate.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For an unusual period, use ","type":"text"},{"text":"Generate one by hand","type":"text","marks":[{"type":"bold"}]},{"text":" at the bottom of the list.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An affidavit lists only credits that aired.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-affidavits' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Setup","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/setup"}}]},{"text":" holds the lists the rest of the tool depends on. Each card says whether it needs attention.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Inventory pools","type":"text","marks":[{"type":"bold"}]},{"text":": what an order''s “AM Drive” or “Carpool” means in On Air programs and time windows. A pool with no mapping can''t be scheduled.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Industries","type":"text","marks":[{"type":"bold"}]},{"text":": the categories auto-fill uses to keep competing underwriters out of the same break.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Import agreements","type":"text","marks":[{"type":"bold"}]},{"text":" and ","type":"text"},{"text":"Import copy","type":"text","marks":[{"type":"bold"}]},{"text":": the one-time moves from RadioTraffic. Only administrators see these.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='underwriting-setup' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Settings","type":"text","marks":[{"type":"link","attrs":{"href":"/editorial/settings"}}]},{"text":" is for editors. It has three parts: ","type":"text"},{"text":"Submission form","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Pillars","type":"text","marks":[{"type":"bold"}]},{"text":", and ","type":"text"},{"text":"Rubric","type":"text","marks":[{"type":"bold"}]},{"text":". Retired entries stay on the pitches and scores that used them, so nothing changed here rewrites history.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Submission form","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"+ Add field","type":"text","marks":[{"type":"bold"}]},{"text":" to add a question to the pitch form. A field''s type is fixed once it exists; its label, help text, options, and whether it''s required can change later.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reorder fields with the arrows. Retire a field you no longer need; restore it any time.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pillars","type":"text"}]},{"type":"paragraph","content":[{"text":"Pillars are the station''s coverage priorities. Each has a guiding question, shown to writers on the pitch form. Retire a pillar to take it off the form; a retired pillar can be deleted.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rubric","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Criteria belong to a rubric profile. Core criteria are weighted and averaged; the weights in a profile should add up to 100. Modifiers are scored separately and never count toward the core average.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Each criterion can carry anchored descriptions — what each score means — which reviewers see when they hover a score.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A weight change applies to future scoring only. The scoring scale and the modifier threshold are set at the bottom of the page.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='editorial-configure-form-and-rubric' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"project","type":"text","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"text":" starts with one file — a recording, or a PDF document.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Create a project","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Sourcework home page, select ","type":"text"},{"text":"New project","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a file: audio (WAV, MP3, M4A/AAC), video (MP4, MOV, WebM), or a PDF.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The title fills in from the file name — change it to whatever you''ll look for later.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Add optional notes for context, then select ","type":"text"},{"text":"Upload and create project","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"While it processes","type":"text"}]},{"type":"paragraph","content":[{"text":"The button shows its own progress — ","type":"text"},{"text":"Uploading…","type":"text","marks":[{"type":"italic"}]},{"text":", then ","type":"text"},{"text":"Finishing up…","type":"text","marks":[{"type":"italic"}]},{"text":" — before it takes you to the new project. Processing continues from there in the background: a banner explains what''s still running, and the page updates on its own once it''s done.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Audio and video get a transcript.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A PDF''s text is extracted automatically — a plain read of the file first, falling back to OCR only when that isn''t enough.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If processing fails, the project page offers ","type":"text"},{"text":"Retry transcription","type":"text","marks":[{"type":"bold"}]},{"text":" or ","type":"text"},{"text":"Retry text extraction","type":"text","marks":[{"type":"bold"}]},{"text":". Either way, the file itself is already safely uploaded.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Anything outside the accepted audio, video, and PDF types is rejected before the upload starts, with a message naming what is accepted.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The file goes straight from your browser to storage. A long recording can take a few minutes to upload — most of that time is the upload itself, not processing.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Once a source is uploaded, it can be used in more than one project with no re-upload — see ","type":"text"},{"text":"Reference another source in a project","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='sourcework-starting-a-project' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Every ","type":"text"},{"text":"project","type":"text","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"text":"''s transcript is on the left. Excerpts — short clips saved for reuse — are pulled from it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Create an excerpt","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Drag to select the stretch of text you want, in the transcript.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"New excerpt","type":"text","marks":[{"type":"bold"}]},{"text":" panel opens, showing the time range and the quoted text.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Give it a title, then select ","type":"text"},{"text":"Create excerpt","type":"text","marks":[{"type":"bold"}]},{"text":" — or ","type":"text"},{"text":"Preview","type":"text","marks":[{"type":"bold"}]},{"text":" first to listen to the exact range.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Working with excerpts","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Excerpts panel lists every one you''ve made, with the count in its heading.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nudge the start or end of a clip with the trim buttons — a small step or a larger one.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Export WAV","type":"text","marks":[{"type":"bold"}]},{"text":" renders the clip to its own audio file; ","type":"text"},{"text":"Download","type":"text","marks":[{"type":"bold"}]},{"text":" appears once that''s ready. ","type":"text"},{"text":"Export all (zip)","type":"text","marks":[{"type":"bold"}]},{"text":" does every excerpt in the project at once.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select a card''s title to rename it. ","type":"text"},{"text":"Delete","type":"text","marks":[{"type":"bold"}]},{"text":" asks you to confirm before it removes one.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range — its excerpts appear in the same panel.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trimming a clip after it''s been exported makes that export stale. Re-export before you rely on the download.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A search box above the panel searches this source''s transcript and its excerpts together.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='sourcework-transcript-and-excerpts' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The search box on the ","type":"text"},{"text":"Sourcework home page","type":"text","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"text":" searches every project, source, transcript, and excerpt you have access to — enter a term and go.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How results work","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Results are ranked by relevance and labeled by kind — project, transcript, document, or excerpt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Clear search","type":"text","marks":[{"type":"bold"}]},{"text":" to return to the ordinary project list.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The same kind of search box appears again inside a project workspace and inside the Excerpts panel, narrowed to just that source.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The hint line under the search box says what kind of search is active: “Searches what was said and what it was about” once topic search is configured for this portal, or “Searches the words that were said” — an exact match only — when it isn''t.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Topic search (finding a passage by what it''s about, not just its exact wording) depends on an optional service being configured. If it''s off, keyword search still finds everything — it just won''t catch a paraphrase.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nothing errors when topic search is off. The hint line under the box is the only place this is shown.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='sourcework-search' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Curators decide what happens to each request. A curator is anyone an administrator has given the Curator role on ","type":"text"},{"text":"Roadmap","type":"text","marks":[{"type":"link","attrs":{"href":"/roadmap"}}]},{"text":"; administrators curate too.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Move a request","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the Roadmap. As a curator you see a board with a column for each of the six statuses.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Drag a card to the status it should have. A move the status rules don''t allow is ignored and the card returns to its column.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dropping a card on ","type":"text"},{"text":"Declined","type":"text","marks":[{"type":"bold"}]},{"text":" asks for a reason first. The reason is shown on the request.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"You can also change a request''s status from its own page.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Everyone else sees the grouped list of decided requests, not the board.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Status changes are recorded in the audit log.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='roadmap-curate-requests' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"An answer worth transcribing can be handed to Sourcework directly from its ","type":"text"},{"text":"submission page","type":"text","marks":[{"type":"link","attrs":{"href":"/audience-listening"}}]},{"text":" — one answer at a time, or, for a query set to automatic transcription, in a batch.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Send one answer","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On a submission''s page, under an answered question, select ","type":"text"},{"text":"Send to transcription","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"This creates a Sourcework project from the answer''s audio and starts transcription. You stay on the submission page — it doesn''t navigate you away.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Once it succeeds, the answer''s badge updates and an ","type":"text"},{"text":"Open in Sourcework","type":"text","marks":[{"type":"bold"}]},{"text":" link appears, showing the project''s current status. Select it when you''re ready to leave for Sourcework.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Automatic queries","type":"text"}]},{"type":"paragraph","content":[{"text":"If the query''s settings have transcription set to automatic, every submitted answer is queued on its own. A banner above the Submissions list shows how many are queued, with a ","type":"text"},{"text":"Send queued answers","type":"text","marks":[{"type":"bold"}]},{"text":" button that sends the whole batch in one click — still a manual click, since there''s no background job runner.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sending needs both Audience Listening and Sourcework access. Without the second, the button fails with a message telling you to ask an administrator for it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Only what the participant consented to carries over — never their contact details, and their name or city only if they didn''t ask to stay anonymous.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If a send fails, the button becomes ","type":"text"},{"text":"Retry transcription","type":"text","marks":[{"type":"bold"}]},{"text":" and the error is shown right there on the page.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen links preserved in the existing guide' where slug='audience-listening-send-to-sourcework' and edited_since_release=false and body::text not like '%"href"%';

update public.rc_articles set body=jsonb_set(body,'{content,0,content,2,text}',to_jsonb(replace(body #>> '{content,0,content,2,text}','university production work','university and outside production work'))),version_note='Clarified that requests include external partners as well as university units' where slug='bookings-requests' and body #>> '{content,0,content,2,text}' like '%university production work%';
